arguments.command:
cd /testbed && source /opt/miniconda3/bin/activate testbed && python -c "
import cantools
files = ['tests/files/kcd/tester.kcd', 'tests/files/kcd/vehicle.kcd', 'tests/files/kcd/dump.kcd', 'tests/files/kcd/empty.kcd', 'tests/files/kcd/signal_range.kcd']
for f in files:
    try:
        db = cantools.database.load_file(f)
        print(f'{f}: Loaded successfully! Messages: {len(db.messages)}')
    except Exception as e:
        print(f'{f}: ERROR - {e}')
"

